import type { HapticsAdapter } from '../types';
import { Capacitor } from '@capacitor/core';

/**
 * Haptics adapter interface for cross-platform vibration support.
 * Automatically detects platform and uses appropriate haptics implementation.
 */

// Import all haptics implementations
import { nativeHapticsAdapter } from './nativeHaptics';
import { webVibrationAdapter } from './webVibration';
import { noopAdapter } from './noop';

// Auto-detect platform and choose appropriate adapter
export const hapticsAdapter: HapticsAdapter = (() => {
  // If running on native mobile platform (iOS/Android), use native haptics
  if (Capacitor.isNativePlatform()) {
    return nativeHapticsAdapter;
  }

  // If running in web browser with vibration support, use web vibration
  if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
    return webVibrationAdapter;
  }

  // Fallback to no-op for unsupported environments
  return noopAdapter;
})();

// Re-export types for convenience
export type { HapticsAdapter } from '../types';

