import type { VibeImplementation, VibeInstance, VibeOptions } from '../types';
import { hapticsAdapter } from '../haptics/adapter';
import { getAudioEngine } from '../audio/engine';

/**
 * Scratch vibe implementation - finger movement across canvas produces:
 * - Visual: streaks that disturb a noise field
 * - Haptics: short buzzes on velocity spikes
 * - Audio: scratch texture that modulates with speed
 */

interface Point {
  x: number;
  y: number;
  timestamp: number;
}

interface Stroke {
  points: Point[];
  intensity: number;
  fadeStart: number;
}

class ScratchVibeInstance implements VibeInstance {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private options: VibeOptions;
  private animationId: number | null = null;
  private isDrawing = false;
  private currentStroke: Point[] = [];
  private strokes: Stroke[] = [];
  private lastPoint: Point | null = null;
  private lastVibration = 0;
  private noiseField: ImageData | null = null;
  private audioEngine = getAudioEngine();

  // Performance tracking
  private frameCount = 0;
  private lastFpsCheck = performance.now();

  constructor(canvas: HTMLCanvasElement, options: VibeOptions) {
    this.canvas = canvas;
    this.options = options;

    const ctx = canvas.getContext('2d');
    if (!ctx) {
      throw new Error('Could not get 2D context from canvas');
    }
    this.ctx = ctx;

    this.setupCanvas();
    this.generateNoiseField();
    this.bindEvents();
    this.startRenderLoop();
  }

  private setupCanvas(): void {
    const dpr = window.devicePixelRatio || 1;
    const rect = this.canvas.getBoundingClientRect();

    // Set actual size in memory (scaled for pixel density)
    this.canvas.width = rect.width * dpr;
    this.canvas.height = rect.height * dpr;

    // Scale drawing context
    this.ctx.scale(dpr, dpr);

    // Set display size
    this.canvas.style.width = rect.width + 'px';
    this.canvas.style.height = rect.height + 'px';

    // Configure context for smooth drawing
    this.ctx.lineCap = 'round';
    this.ctx.lineJoin = 'round';
    this.ctx.imageSmoothingEnabled = true;
  }

  private generateNoiseField(): void {
    const width = this.canvas.width;
    const height = this.canvas.height;

    this.noiseField = this.ctx.createImageData(width, height);
    const data = this.noiseField.data;

    // Generate Perlin-like noise field
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const index = (y * width + x) * 4;

        // Multi-octave noise for more natural texture
        const noise = this.noise(x * 0.01, y * 0.01) * 0.5 +
                     this.noise(x * 0.02, y * 0.02) * 0.25 +
                     this.noise(x * 0.04, y * 0.04) * 0.125;

        const value = Math.floor((noise + 1) * 127.5); // Normalize to 0-255

        // Create subtle texture
        data[index] = value * 0.1;     // R
        data[index + 1] = value * 0.15; // G
        data[index + 2] = value * 0.2;  // B
        data[index + 3] = 20;           // A (very subtle)
      }
    }
  }

  private noise(x: number, y: number): number {
    // Simple value noise implementation
    const X = Math.floor(x) & 255;
    const Y = Math.floor(y) & 255;

    x -= Math.floor(x);
    y -= Math.floor(y);

    const u = this.fade(x);
    const v = this.fade(y);

    const A = this.p[X] + Y;
    const B = this.p[X + 1] + Y;

    return this.lerp(v,
      this.lerp(u, this.grad(this.p[A], x, y), this.grad(this.p[B], x - 1, y)),
      this.lerp(u, this.grad(this.p[A + 1], x, y - 1), this.grad(this.p[B + 1], x - 1, y - 1))
    );
  }

  private fade(t: number): number {
    return t * t * t * (t * (t * 6 - 15) + 10);
  }

  private lerp(t: number, a: number, b: number): number {
    return a + t * (b - a);
  }

  private grad(hash: number, x: number, y: number): number {
    const h = hash & 3;
    const u = h < 2 ? x : y;
    const v = h < 2 ? y : x;
    return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
  }

  // Permutation table for noise
  private p = [
    151,160,137,91,90,15,131,13,201,95,96,53,194,233,7,225,140,36,103,30,69,142,
    8,99,37,240,21,10,23,190,6,148,247,120,234,75,0,26,197,62,94,252,219,203,117,
    35,11,32,57,177,33,88,237,149,56,87,174,20,125,136,171,168,68,175,74,165,71,
    134,139,48,27,166,77,146,158,231,83,111,229,122,60,211,133,230,220,105,92,41,
    55,46,245,40,244,102,143,54,65,25,63,161,1,216,80,73,209,76,132,187,208,89,
    18,169,200,196,135,130,116,188,159,86,164,100,109,198,173,186,3,64,52,217,226,
    250,124,123,5,202,38,147,118,126,255,82,85,212,207,206,59,227,47,16,58,17,182,
    189,28,42,223,183,170,213,119,248,152,2,44,154,163,70,221,153,101,155,167,43,
    172,9,129,22,39,253,19,98,108,110,79,113,224,232,178,185,112,104,218,246,97,
    228,251,34,242,193,238,210,144,12,191,179,162,241,81,51,145,235,249,14,239,
    107,49,192,214,31,181,199,106,157,184,84,204,176,115,121,50,45,127,4,150,254,
    138,236,205,93,222,114,67,29,24,72,243,141,128,195,78,66,215,61,156,180
  ];

  private bindEvents(): void {
    // Mouse events
    this.canvas.addEventListener('mousedown', this.handlePointerStart.bind(this));
    this.canvas.addEventListener('mousemove', this.handlePointerMove.bind(this));
    this.canvas.addEventListener('mouseup', this.handlePointerEnd.bind(this));
    this.canvas.addEventListener('mouseleave', this.handlePointerEnd.bind(this));

    // Touch events
    this.canvas.addEventListener('touchstart', this.handleTouchStart.bind(this), { passive: false });
    this.canvas.addEventListener('touchmove', this.handleTouchMove.bind(this), { passive: false });
    this.canvas.addEventListener('touchend', this.handlePointerEnd.bind(this));
    this.canvas.addEventListener('touchcancel', this.handlePointerEnd.bind(this));

    // Keyboard alternative (accessibility)
    this.canvas.addEventListener('keydown', this.handleKeyDown.bind(this));
    this.canvas.addEventListener('keyup', this.handleKeyUp.bind(this));

    // Make canvas focusable
    this.canvas.tabIndex = 0;
  }

  private handlePointerStart(event: MouseEvent): void {
    event.preventDefault();
    const rect = this.canvas.getBoundingClientRect();
    const point = {
      x: event.clientX - rect.left,
      y: event.clientY - rect.top,
      timestamp: performance.now()
    };

    this.startStroke(point);
  }

  private handlePointerMove(event: MouseEvent): void {
    if (!this.isDrawing) return;

    event.preventDefault();
    const rect = this.canvas.getBoundingClientRect();
    const point = {
      x: event.clientX - rect.left,
      y: event.clientY - rect.top,
      timestamp: performance.now()
    };

    this.addToStroke(point);
  }

  private handlePointerEnd(event: Event): void {
    event.preventDefault();
    this.endStroke();
  }

  private handleTouchStart(event: TouchEvent): void {
    event.preventDefault();
    const touch = event.touches[0];
    if (!touch) return;

    const rect = this.canvas.getBoundingClientRect();
    const point = {
      x: touch.clientX - rect.left,
      y: touch.clientY - rect.top,
      timestamp: performance.now()
    };

    this.startStroke(point);
  }

  private handleTouchMove(event: TouchEvent): void {
    if (!this.isDrawing) return;

    event.preventDefault();
    const touch = event.touches[0];
    if (!touch) return;

    const rect = this.canvas.getBoundingClientRect();
    const point = {
      x: touch.clientX - rect.left,
      y: touch.clientY - rect.top,
      timestamp: performance.now()
    };

    this.addToStroke(point);
  }

  private handleKeyDown(event: KeyboardEvent): void {
    if (event.key === ' ' || event.key === 'Enter') {
      event.preventDefault();
      if (!this.isDrawing) {
        // Start drawing at center of canvas
        const rect = this.canvas.getBoundingClientRect();
        const point = {
          x: rect.width / 2,
          y: rect.height / 2,
          timestamp: performance.now()
        };
        this.startStroke(point);
      }
    }
  }

  private handleKeyUp(event: KeyboardEvent): void {
    if (event.key === ' ' || event.key === 'Enter') {
      event.preventDefault();
      this.endStroke();
    }
  }

  private startStroke(point: Point): void {
    this.isDrawing = true;
    this.currentStroke = [point];
    this.lastPoint = point;

    // Initial haptic feedback
    if (this.options.hapticsEnabled) {
      hapticsAdapter.vibrate(10);
    }
  }

  private addToStroke(point: Point): void {
    if (!this.isDrawing || !this.lastPoint) return;

    this.currentStroke.push(point);

    // Calculate velocity for haptic and audio feedback
    const dx = point.x - this.lastPoint.x;
    const dy = point.y - this.lastPoint.y;
    const dt = point.timestamp - this.lastPoint.timestamp;
    const velocity = Math.sqrt(dx * dx + dy * dy) / Math.max(dt, 1);

    // Haptic feedback on velocity spikes
    if (this.options.hapticsEnabled && velocity > 2 &&
        point.timestamp - this.lastVibration > 80) {
      const intensity = Math.min(velocity * 2, 15);
      hapticsAdapter.vibrate(Math.floor(intensity));
      this.lastVibration = point.timestamp;
    }

    // Audio feedback
    if (this.options.audioEnabled) {
      const intensity = Math.min(velocity / 10, 1);
      // Fire and forget - don't block on audio
      this.audioEngine.playScratch(intensity).catch(err =>
        console.debug('Audio playback failed:', err)
      );
    }

    this.lastPoint = point;
  }

  private endStroke(): void {
    if (!this.isDrawing) return;

    this.isDrawing = false;

    if (this.currentStroke.length > 1) {
      // Calculate stroke intensity based on total path length and speed
      let totalLength = 0;
      let totalTime = 0;

      for (let i = 1; i < this.currentStroke.length; i++) {
        const prev = this.currentStroke[i - 1];
        const curr = this.currentStroke[i];
        const dx = curr.x - prev.x;
        const dy = curr.y - prev.y;
        totalLength += Math.sqrt(dx * dx + dy * dy);
        totalTime += curr.timestamp - prev.timestamp;
      }

      const avgSpeed = totalLength / Math.max(totalTime, 1);
      const intensity = Math.min(avgSpeed * 0.1, 1);

      this.strokes.push({
        points: [...this.currentStroke],
        intensity,
        fadeStart: performance.now()
      });
    }

    this.currentStroke = [];
    this.lastPoint = null;

    // End haptic feedback
    if (this.options.hapticsEnabled) {
      hapticsAdapter.vibrate(5);
    }
  }

  private startRenderLoop(): void {
    const render = () => {
      this.render();
      this.frameCount++;

      // Performance monitoring (keep under 2% main thread)
      if (this.frameCount % 60 === 0) {
        const now = performance.now();
        const fps = 60000 / (now - this.lastFpsCheck);
        this.lastFpsCheck = now;

        if (fps < 55) {
          console.warn('Scratch vibe performance degraded:', fps, 'fps');
        }
      }

      this.animationId = requestAnimationFrame(render);
    };

    this.animationId = requestAnimationFrame(render);
  }

  private render(): void {
    const now = performance.now();

    // Clear canvas
    this.ctx.fillStyle = '#1a1a1a';
    this.ctx.fillRect(0, 0, this.canvas.width / (window.devicePixelRatio || 1),
                            this.canvas.height / (window.devicePixelRatio || 1));

    // Draw noise field (subtle background texture)
    if (this.noiseField && !this.options.reduceMotion) {
      this.ctx.putImageData(this.noiseField, 0, 0);
    }

    // Draw completed strokes with fade
    this.strokes = this.strokes.filter(stroke => {
      const age = now - stroke.fadeStart;
      const maxAge = 3000; // 3 seconds fade

      if (age > maxAge) return false;

      const alpha = 1 - (age / maxAge);
      this.drawStroke(stroke.points, stroke.intensity * alpha);

      return true;
    });

    // Draw current stroke
    if (this.isDrawing && this.currentStroke.length > 1) {
      this.drawStroke(this.currentStroke, 1);
    }
  }

  private drawStroke(points: Point[], alpha: number): void {
    if (points.length < 2) return;

    this.ctx.save();
    this.ctx.globalAlpha = alpha;

    // Draw main stroke
    this.ctx.beginPath();
    this.ctx.moveTo(points[0].x, points[0].y);

    for (let i = 1; i < points.length; i++) {
      const prev = points[i - 1];
      const curr = points[i];

      // Calculate dynamic stroke width based on velocity
      const dx = curr.x - prev.x;
      const dy = curr.y - prev.y;
      const dt = curr.timestamp - prev.timestamp;
      const velocity = Math.sqrt(dx * dx + dy * dy) / Math.max(dt, 1);
      const width = Math.max(1, Math.min(velocity * 0.5, 8));

      this.ctx.lineWidth = width;
      this.ctx.strokeStyle = `rgba(99, 102, 241, ${alpha})`;
      this.ctx.lineTo(curr.x, curr.y);
    }

    this.ctx.stroke();

    // Add glow effect if not reducing motion
    if (!this.options.reduceMotion) {
      this.ctx.shadowColor = 'rgba(99, 102, 241, 0.5)';
      this.ctx.shadowBlur = 10;
      this.ctx.stroke();
    }

    this.ctx.restore();
  }

  unmount(): void {
    if (this.animationId) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }

    // Remove event listeners
    this.canvas.removeEventListener('mousedown', this.handlePointerStart.bind(this));
    this.canvas.removeEventListener('mousemove', this.handlePointerMove.bind(this));
    this.canvas.removeEventListener('mouseup', this.handlePointerEnd.bind(this));
    this.canvas.removeEventListener('mouseleave', this.handlePointerEnd.bind(this));
    this.canvas.removeEventListener('touchstart', this.handleTouchStart.bind(this));
    this.canvas.removeEventListener('touchmove', this.handleTouchMove.bind(this));
    this.canvas.removeEventListener('touchend', this.handlePointerEnd.bind(this));
    this.canvas.removeEventListener('touchcancel', this.handlePointerEnd.bind(this));
    this.canvas.removeEventListener('keydown', this.handleKeyDown.bind(this));
    this.canvas.removeEventListener('keyup', this.handleKeyUp.bind(this));

    // Clear canvas
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
  }
}

export const scratchVibe: VibeImplementation = {
  mount(canvas: HTMLCanvasElement, options: VibeOptions): VibeInstance {
    return new ScratchVibeInstance(canvas, options);
  }
};

