<script lang="ts">
  import { onMount } from 'svelte';
  import type { UserSettings } from './types';
  import { getStorage } from './db/storage';
  import { getAudioEngine } from './audio/engine';
  import { currentRoute, userSettings } from './stores';

  // Route components
  import Home from './routes/Home.svelte';
  import Session from './routes/Session.svelte';
  import Trends from './routes/Trends.svelte';
  import Settings from './routes/Settings.svelte';

  let initialized = false;
  let showDisclaimer = false;

  onMount(async () => {
    try {
      // Initialize storage and load settings
      const storage = getStorage();
      const settings = await storage.getSettings();
      userSettings.set(settings);

      // Audio engine will be initialized lazily on first use (after user gesture)
      const audioEngine = getAudioEngine();
      audioEngine.setEnabled(settings.audioEnabled);

      // Show disclaimer if first time
      if (!settings.hasSeenDisclaimer) {
        showDisclaimer = true;
      }

      initialized = true;
    } catch (error) {
      console.error('App initialization failed:', error);
      initialized = true; // Still show the app
    }
  });

  const dismissDisclaimer = async () => {
    showDisclaimer = false;
    const storage = getStorage();
    await storage.updateSettings({ hasSeenDisclaimer: true });
    userSettings.update(s => ({ ...s, hasSeenDisclaimer: true }));
  };

  $: routeComponent = {
    home: Home,
    session: Session,
    trends: Trends,
    settings: Settings,
  }[$currentRoute];
</script>

{#if !initialized}
  <div class="loading">
    <div class="loading-spinner"></div>
    <p>Initializing Vibe...</p>
  </div>
{:else}
  <main class="app">
    <svelte:component this={routeComponent} />
  </main>

  {#if showDisclaimer}
    <div class="disclaimer-overlay" role="dialog" aria-modal="true" aria-labelledby="disclaimer-title">
      <div class="disclaimer-content">
        <h2 id="disclaimer-title">Important Notice</h2>
        <p>
          <strong>Vibe is a support tool, not medical advice.</strong>
        </p>
        <p>
          This app is designed to help redirect tactile urges through sensory substitution.
          It is not a medical device and should not replace professional healthcare advice
          or treatment.
        </p>
        <p>
          If you're experiencing persistent urges or self-harm thoughts, please consult
          with a healthcare professional or contact a crisis helpline.
        </p>
        <button class="disclaimer-button" on:click={dismissDisclaimer}>
          I Understand
        </button>
      </div>
    </div>
  {/if}
{/if}

