<script lang="ts">
  import { currentRoute, userSettings } from '../stores';
  import { sessionMachine, canStartNewSession, getTimeUntilNextSession } from '../state/sessionMachine.ts';
  import { createActor } from 'xstate';
  import { readable } from 'svelte/store';
  import Button from '../ui/Button.svelte';
  import type { VibeType, VibeConfig } from '../types';

  // Create XState v5 actor and reactive store
  const actor = createActor(sessionMachine);
  actor.start();

  const state = readable(actor.getSnapshot(), (set) => {
    const subscription = actor.subscribe(set);
    return () => subscription.unsubscribe();
  });

  const send = actor.send.bind(actor);

  // Available vibes configuration
  const vibes: VibeConfig[] = [
    {
      type: 'scratch',
      name: 'Scratch',
      description: 'Draw across the canvas with velocity-responsive textures'
    },
    {
      type: 'press',
      name: 'Press',
      description: 'Long-press to create pulsing pressure ripples'
    }
  ];

  let selectedVibe: VibeType = 'scratch';
  let cooldownTime = 0;
  let cooldownInterval: number | null = null;

  const startSession = (vibeType: VibeType) => {
    if (!canStartNewSession($state.context)) {
      return; // Shouldn't happen due to UI state, but safety check
    }

    selectedVibe = vibeType;
    currentRoute.set('session');
  };

  const goToTrends = () => {
    currentRoute.set('trends');
  };

  const goToSettings = () => {
    currentRoute.set('settings');
  };

  // Update cooldown timer
  const updateCooldown = () => {
    cooldownTime = getTimeUntilNextSession($state.context);
    if (cooldownTime === 0 && cooldownInterval) {
      clearInterval(cooldownInterval);
      cooldownInterval = null;
    }
  };

  // Start cooldown timer if needed
  $: if ($state.context.lastSessionEnd > 0 && cooldownTime > 0 && !cooldownInterval) {
    cooldownInterval = setInterval(updateCooldown, 1000);
    updateCooldown();
  }

  // Cleanup interval on component destroy
  $: if (cooldownInterval && cooldownTime === 0) {
    clearInterval(cooldownInterval);
    cooldownInterval = null;
  }

  $: canStart = canStartNewSession($state.context);
</script>

<div class="home">
  <div class="container">
    <header class="home-header">
      <h1 class="home-title">Vibe</h1>
      <p class="home-subtitle">Pick a vibe to ride the urge.</p>
    </header>

    <main class="home-main">
      {#if !canStart}
        <div class="cooldown-notice">
          <h3>Take a moment</h3>
          <p>Next session available in {cooldownTime}s</p>
          <div class="cooldown-bar">
            <div
              class="cooldown-progress"
              style="width: {((30 - cooldownTime) / 30) * 100}%"
            ></div>
          </div>
        </div>
      {/if}

      <div class="vibes-grid" class:disabled={!canStart}>
        {#each vibes as vibe}
          <button
            class="vibe-card"
            class:disabled={!canStart}
            disabled={!canStart}
            on:click={() => startSession(vibe.type)}
          >
            <div class="vibe-icon" class:scratch={vibe.type === 'scratch'} class:press={vibe.type === 'press'}>
              {#if vibe.type === 'scratch'}
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.94-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/>
                </svg>
              {:else}
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8z"/>
                  <circle cx="12" cy="12" r="3"/>
                </svg>
              {/if}
            </div>
            <h3 class="vibe-name">{vibe.name}</h3>
            <p class="vibe-description">{vibe.description}</p>
          </button>
        {/each}
      </div>
    </main>

    <footer class="home-footer">
      <div class="nav-buttons">
        <Button variant="ghost" size="sm" on:click={goToTrends}>
          Trends
        </Button>
        <Button variant="ghost" size="sm" on:click={goToSettings}>
          Settings
        </Button>
      </div>
    </footer>
  </div>
</div>

