import type { HapticsAdapter } from '../types';

/**
 * No-op haptics adapter for environments without vibration support.
 * Used as fallback on desktop or unsupported browsers.
 */
export const noopAdapter: HapticsAdapter = {
  async vibrate(_pattern: number | number[]): Promise<void> {
    // No-op - silently do nothing
  },

  canVibrate(): boolean {
    return false;
  }
};

