import type { AudioEngine } from '../types';

/**
 * WebAudio engine for generating scratch and press sound effects.
 * Uses oscillators and noise for texture sounds with real-time modulation.
 */
export class WebAudioEngine implements AudioEngine {
  private context: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private scratchGain: GainNode | null = null;
  private pressGain: GainNode | null = null;
  private noiseBuffer: AudioBuffer | null = null;
  private enabled = true;
  private volume = 0.7;
  private initialized = false;

  async initialize(): Promise<void> {
    // Don't create AudioContext until first user interaction
    // This will be called lazily when audio is first needed
    this.initialized = true;
  }

  private async ensureAudioContext(): Promise<boolean> {
    if (!this.enabled || this.context) {
      return this.context !== null;
    }

    try {
      // Create audio context (must be after user gesture)
      this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

      // Resume context if suspended (required by some browsers)
      if (this.context.state === 'suspended') {
        await this.context.resume();
      }

      // Create master gain node
      this.masterGain = this.context.createGain();
      this.masterGain.connect(this.context.destination);
      this.masterGain.gain.value = this.volume;

      // Create gain nodes for each sound type
      this.scratchGain = this.context.createGain();
      this.scratchGain.connect(this.masterGain);
      this.scratchGain.gain.value = 0.6;

      this.pressGain = this.context.createGain();
      this.pressGain.connect(this.masterGain);
      this.pressGain.gain.value = 0.8;

      // Generate noise buffer for scratch texture
      await this.generateNoiseBuffer();

      return true;
    } catch (error) {
      console.warn('Audio initialization failed:', error);
      return false;
    }
  }

  destroy(): void {
    if (this.context) {
      this.context.close();
      this.context = null;
    }
    this.masterGain = null;
    this.scratchGain = null;
    this.pressGain = null;
    this.noiseBuffer = null;
  }

  async playScratch(intensity: number): Promise<void> {
    if (!this.enabled) return;

    // Lazy initialization on first use (after user gesture)
    const hasAudio = await this.ensureAudioContext();
    if (!hasAudio || !this.context || !this.scratchGain || !this.noiseBuffer) return;

    try {
      const now = this.context.currentTime;

      // Create noise source
      const source = this.context.createBufferSource();
      source.buffer = this.noiseBuffer;
      source.loop = true;

      // Create filter for texture modulation
      const filter = this.context.createBiquadFilter();
      filter.type = 'bandpass';
      filter.frequency.value = 200 + (intensity * 800); // 200-1000 Hz based on intensity
      filter.Q.value = 2 + (intensity * 3); // Sharper filter at higher intensity

      // Create envelope gain
      const envelope = this.context.createGain();
      envelope.gain.setValueAtTime(0, now);
      envelope.gain.linearRampToValueAtTime(intensity * 0.3, now + 0.01);
      envelope.gain.exponentialRampToValueAtTime(0.001, now + 0.1);

      // Connect nodes
      source.connect(filter);
      filter.connect(envelope);
      envelope.connect(this.scratchGain);

      // Play and cleanup
      source.start(now);
      source.stop(now + 0.1);

      // Cleanup after sound ends
      setTimeout(() => {
        try {
          source.disconnect();
          filter.disconnect();
          envelope.disconnect();
        } catch (e) {
          // Node might already be disconnected
        }
      }, 150);

    } catch (error) {
      console.warn('Scratch audio failed:', error);
    }
  }

  async playPress(intensity: number): Promise<void> {
    if (!this.enabled) return;

    // Lazy initialization on first use (after user gesture)
    const hasAudio = await this.ensureAudioContext();
    if (!hasAudio || !this.context || !this.pressGain) return;

    try {
      const now = this.context.currentTime;

      // Create low-frequency oscillator for "thump"
      const osc = this.context.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(40 + (intensity * 20), now); // 40-60 Hz

      // Create envelope with ADSR characteristics
      const envelope = this.context.createGain();
      envelope.gain.setValueAtTime(0, now);
      envelope.gain.linearRampToValueAtTime(intensity * 0.5, now + 0.05); // Attack
      envelope.gain.linearRampToValueAtTime(intensity * 0.3, now + 0.1);  // Decay
      envelope.gain.exponentialRampToValueAtTime(0.001, now + 0.4);       // Release

      // Add slight distortion with wave shaper for texture
      const shaper = this.context.createWaveShaper();
      shaper.curve = this.createDistortionCurve(intensity * 10);

      // Connect nodes
      osc.connect(shaper);
      shaper.connect(envelope);
      envelope.connect(this.pressGain);

      // Play and cleanup
      osc.start(now);
      osc.stop(now + 0.4);

      // Cleanup after sound ends
      setTimeout(() => {
        try {
          osc.disconnect();
          shaper.disconnect();
          envelope.disconnect();
        } catch (e) {
          // Node might already be disconnected
        }
      }, 450);

    } catch (error) {
      console.warn('Press audio failed:', error);
    }
  }

  setVolume(volume: number): void {
    this.volume = Math.max(0, Math.min(1, volume));
    if (this.masterGain) {
      this.masterGain.gain.value = this.volume;
    }
  }

  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    if (this.masterGain) {
      this.masterGain.gain.value = enabled ? this.volume : 0;
    }
  }

  private async generateNoiseBuffer(): Promise<void> {
    if (!this.context) return;

    const bufferSize = this.context.sampleRate * 0.1; // 100ms of noise
    this.noiseBuffer = this.context.createBuffer(1, bufferSize, this.context.sampleRate);
    const output = this.noiseBuffer.getChannelData(0);

    // Generate pink noise (more natural sounding than white noise)
    let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;

    for (let i = 0; i < bufferSize; i++) {
      const white = Math.random() * 2 - 1;

      // Pink noise filter
      b0 = 0.99886 * b0 + white * 0.0555179;
      b1 = 0.99332 * b1 + white * 0.0750759;
      b2 = 0.96900 * b2 + white * 0.1538520;
      b3 = 0.86650 * b3 + white * 0.3104856;
      b4 = 0.55000 * b4 + white * 0.5329522;
      b5 = -0.7616 * b5 - white * 0.0168980;

      output[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362) * 0.11;
      b6 = white * 0.115926;
    }
  }

  private createDistortionCurve(amount: number): Float32Array {
    const samples = 44100;
    const curve = new Float32Array(samples);
    const deg = Math.PI / 180;

    for (let i = 0; i < samples; i++) {
      const x = (i * 2) / samples - 1;
      curve[i] = ((3 + amount) * x * 20 * deg) / (Math.PI + amount * Math.abs(x));
    }

    return curve;
  }
}

// Singleton instance
let audioEngine: WebAudioEngine | null = null;

export const getAudioEngine = (): WebAudioEngine => {
  if (!audioEngine) {
    audioEngine = new WebAudioEngine();
  }
  return audioEngine;
};

