import { createMachine, assign } from 'xstate';
import type { SessionContext, VibeType } from '../types';

/**
 * Session state machine for managing the complete session flow:
 * idle -> precheck -> running -> cooldown -> review -> idle
 */

export interface SessionMachineContext extends SessionContext {
  lastSessionEnd: number;
  error?: string;
}

export type SessionEvent =
  | { type: 'START_SESSION'; vibeType: VibeType; beforeIntensity: number; sessionLength: number }
  | { type: 'BEGIN_VIBE' }
  | { type: 'COMPLETE_VIBE' }
  | { type: 'FINISH_COOLDOWN' }
  | { type: 'SUBMIT_REVIEW'; afterIntensity: number }
  | { type: 'RESET' }
  | { type: 'ERROR'; error: string };

const COOLDOWN_DURATION = 30000; // 30 seconds in milliseconds

export const sessionMachine = createMachine({
  id: 'session',
  types: {} as {
    context: SessionMachineContext;
    events: SessionEvent;
  },
  initial: 'idle',
  context: {
    vibeType: 'scratch',
    beforeIntensity: 5,
    afterIntensity: 5,
    sessionLength: 60,
    startTime: 0,
    endTime: 0,
    lastSessionEnd: 0,
    error: undefined,
  },
  states: {
    idle: {
      on: {
        START_SESSION: {
          target: 'precheck',
          guard: 'canStartSession',
          actions: 'setSessionData',
        },
        ERROR: {
          target: 'idle',
          actions: 'setError',
        },
      },
    },

    precheck: {
      entry: 'clearError',
      on: {
        BEGIN_VIBE: {
          target: 'running',
          actions: 'recordStartTime',
        },
        RESET: 'idle',
      },
    },

    running: {
      on: {
        COMPLETE_VIBE: {
          target: 'cooldown',
          actions: 'recordEndTime',
        },
        RESET: {
          target: 'idle',
          actions: 'recordEndTime',
        },
      },
    },

    cooldown: {
      after: {
        3000: 'review', // 3 second cooldown before review
      },
      on: {
        FINISH_COOLDOWN: 'review',
        RESET: 'idle',
      },
    },

    review: {
      on: {
        SUBMIT_REVIEW: {
          target: 'completed',
          actions: 'setAfterIntensity',
        },
        RESET: 'idle',
      },
    },

    completed: {
      entry: 'recordSessionEnd',
      after: {
        2000: 'idle', // Auto-return to idle after 2 seconds
      },
      on: {
        RESET: 'idle',
      },
    },
  },
}, {
  guards: {
    canStartSession: ({ context }) => {
      const now = Date.now();
      const timeSinceLastSession = now - context.lastSessionEnd;
      return timeSinceLastSession >= COOLDOWN_DURATION;
    },
  },
  actions: {
    setSessionData: assign(({ event }) => {
      if (event.type !== 'START_SESSION') return {};
      return {
        vibeType: event.vibeType,
        beforeIntensity: event.beforeIntensity,
        sessionLength: event.sessionLength,
        error: undefined,
      };
    }),

    recordStartTime: assign(() => ({
      startTime: Date.now(),
    })),

    recordEndTime: assign(() => ({
      endTime: Date.now(),
    })),

    setAfterIntensity: assign(({ event }) => {
      if (event.type !== 'SUBMIT_REVIEW') return {};
      return {
        afterIntensity: event.afterIntensity,
      };
    }),

    recordSessionEnd: assign(() => ({
      lastSessionEnd: Date.now(),
    })),

    setError: assign(({ event }) => {
      if (event.type !== 'ERROR') return {};
      return {
        error: event.error,
      };
    }),

    clearError: assign(() => ({
      error: undefined,
    })),
  },
});

// Helper functions for working with the session machine
export const getSessionDuration = (context: SessionMachineContext): number => {
  if (context.startTime === 0) return 0;
  const endTime = context.endTime || Date.now();
  return Math.round((endTime - context.startTime) / 1000);
};

export const getTimeUntilNextSession = (context: SessionMachineContext): number => {
  if (context.lastSessionEnd === 0) return 0;
  const now = Date.now();
  const timeSinceLastSession = now - context.lastSessionEnd;
  const remaining = COOLDOWN_DURATION - timeSinceLastSession;
  return Math.max(0, Math.ceil(remaining / 1000));
};

export const canStartNewSession = (context: SessionMachineContext): boolean => {
  return getTimeUntilNextSession(context) === 0;
};

