import { Haptics, ImpactStyle, NotificationType } from '@capacitor/haptics';
import type { HapticsAdapter } from '../types';

/**
 * Native haptics adapter using @capacitor/haptics for iOS and Android.
 * Provides rich haptic feedback with different impact styles and patterns.
 */
export const nativeHapticsAdapter: HapticsAdapter = {
  async vibrate(pattern: number | number[]): Promise<void> {
    try {
      if (typeof pattern === 'number') {
        // Single vibration - map intensity to impact style
        const style = pattern <= 5 ? ImpactStyle.Light :
                     pattern <= 15 ? ImpactStyle.Medium :
                     ImpactStyle.Heavy;

        await Haptics.impact({ style });
      } else {
        // Pattern array - convert to sequence of impacts and delays
        for (let i = 0; i < pattern.length; i++) {
          const duration = pattern[i];

          if (i % 2 === 0) {
            // Even indices are vibration durations
            if (duration > 0) {
              const style = duration <= 10 ? ImpactStyle.Light :
                           duration <= 20 ? ImpactStyle.Medium :
                           ImpactStyle.Heavy;

              await Haptics.impact({ style });

              // For longer durations, add multiple impacts
              if (duration > 50) {
                const additionalImpacts = Math.floor(duration / 50);
                for (let j = 0; j < additionalImpacts; j++) {
                  await new Promise(resolve => setTimeout(resolve, 50));
                  await Haptics.impact({ style: ImpactStyle.Light });
                }
              }
            }
          } else {
            // Odd indices are pause durations
            if (duration > 0) {
              await new Promise(resolve => setTimeout(resolve, duration));
            }
          }
        }
      }
    } catch (error) {
      console.debug('Native haptics failed, falling back to web vibration:', error);
      // Fallback to web vibration if native haptics fail
      if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
        navigator.vibrate(pattern);
      }
    }
  },

  canVibrate(): boolean {
    // Native haptics are available on mobile platforms
    return true;
  },

  // Additional native haptic methods for enhanced feedback
  async success(): Promise<void> {
    try {
      await Haptics.notification({ type: NotificationType.Success });
    } catch (error) {
      console.debug('Success haptic failed:', error);
    }
  },

  async warning(): Promise<void> {
    try {
      await Haptics.notification({ type: NotificationType.Warning });
    } catch (error) {
      console.debug('Warning haptic failed:', error);
    }
  },

  async error(): Promise<void> {
    try {
      await Haptics.notification({ type: NotificationType.Error });
    } catch (error) {
      console.debug('Error haptic failed:', error);
    }
  },

  async selection(): Promise<void> {
    try {
      await Haptics.selectionStart();
      await new Promise(resolve => setTimeout(resolve, 10));
      await Haptics.selectionChanged();
      await new Promise(resolve => setTimeout(resolve, 10));
      await Haptics.selectionEnd();
    } catch (error) {
      console.debug('Selection haptic failed:', error);
    }
  }
};

