import { openDB, type DBSchema, type IDBPDatabase } from 'idb';
import type { SessionData, UserSettings, StorageAdapter } from '../types';

/**
 * IndexedDB storage adapter for sessions and settings.
 * Uses idb library for cleaner async/await API.
 */

interface VibeDB extends DBSchema {
  sessions: {
    key: string;
    value: SessionData;
    indexes: { 'by-timestamp': number; 'by-vibe-type': string };
  };
  settings: {
    key: string;
    value: any;
  };
}

class IndexedDBStorage implements StorageAdapter {
  private db: IDBPDatabase<VibeDB> | null = null;
  private readonly dbName = 'vibe-db';
  private readonly dbVersion = 1;

  async initialize(): Promise<void> {
    try {
      this.db = await openDB<VibeDB>(this.dbName, this.dbVersion, {
        upgrade(db) {
          // Create sessions store
          const sessionsStore = db.createObjectStore('sessions', {
            keyPath: 'id',
          });
          sessionsStore.createIndex('by-timestamp', 'timestamp');
          sessionsStore.createIndex('by-vibe-type', 'vibeType');

          // Create settings store
          db.createObjectStore('settings');
        },
      });
    } catch (error) {
      console.error('Failed to initialize database:', error);
      throw error;
    }
  }

  async getSessions(): Promise<SessionData[]> {
    if (!this.db) await this.initialize();

    try {
      const sessions = await this.db!.getAll('sessions');
      // Sort by timestamp descending (newest first)
      return sessions.sort((a, b) => b.timestamp - a.timestamp);
    } catch (error) {
      console.error('Failed to get sessions:', error);
      return [];
    }
  }

  async addSession(sessionData: Omit<SessionData, 'id'>): Promise<string> {
    if (!this.db) await this.initialize();

    const session: SessionData = {
      ...sessionData,
      id: this.generateId(),
    };

    try {
      await this.db!.add('sessions', session);
      return session.id;
    } catch (error) {
      console.error('Failed to add session:', error);
      throw error;
    }
  }

  async getSettings(): Promise<UserSettings> {
    if (!this.db) await this.initialize();

    const defaultSettings: UserSettings = {
      hapticsEnabled: true,
      audioEnabled: true,
      reduceMotion: false,
      sessionLength: 90, // 90 seconds default
      hasSeenDisclaimer: false,
    };

    try {
      const stored = await this.db!.get('settings', 'user-settings');
      return stored ? { ...defaultSettings, ...stored } : defaultSettings;
    } catch (error) {
      console.error('Failed to get settings:', error);
      return defaultSettings;
    }
  }

  async updateSettings(settings: Partial<UserSettings>): Promise<void> {
    if (!this.db) await this.initialize();

    try {
      const currentSettings = await this.getSettings();
      const updatedSettings = { ...currentSettings, ...settings };
      await this.db!.put('settings', updatedSettings, 'user-settings');
    } catch (error) {
      console.error('Failed to update settings:', error);
      throw error;
    }
  }

  async clearAllData(): Promise<void> {
    if (!this.db) await this.initialize();

    try {
      const tx = this.db!.transaction(['sessions', 'settings'], 'readwrite');
      await Promise.all([
        tx.objectStore('sessions').clear(),
        tx.objectStore('settings').clear(),
      ]);
      await tx.done;
    } catch (error) {
      console.error('Failed to clear data:', error);
      throw error;
    }
  }

  // Helper methods
  async getSessionsInDateRange(startDate: Date, endDate: Date): Promise<SessionData[]> {
    if (!this.db) await this.initialize();

    try {
      const sessions = await this.db!.getAllFromIndex(
        'sessions',
        'by-timestamp',
        IDBKeyRange.bound(startDate.getTime(), endDate.getTime())
      );
      return sessions.sort((a, b) => b.timestamp - a.timestamp);
    } catch (error) {
      console.error('Failed to get sessions in date range:', error);
      return [];
    }
  }

  async getSessionsByVibeType(vibeType: string): Promise<SessionData[]> {
    if (!this.db) await this.initialize();

    try {
      const sessions = await this.db!.getAllFromIndex('sessions', 'by-vibe-type', vibeType);
      return sessions.sort((a, b) => b.timestamp - a.timestamp);
    } catch (error) {
      console.error('Failed to get sessions by vibe type:', error);
      return [];
    }
  }

  private generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

// Singleton instance
let storage: IndexedDBStorage | null = null;

export const getStorage = (): StorageAdapter => {
  if (!storage) {
    storage = new IndexedDBStorage();
  }
  return storage;
};

// Helper functions for common queries
export const getRecentSessions = async (days: number = 7): Promise<SessionData[]> => {
  const storage = getStorage();
  const endDate = new Date();
  const startDate = new Date(endDate.getTime() - (days * 24 * 60 * 60 * 1000));

  const sessions = await storage.getSessions();
  return sessions.filter(session =>
    session.timestamp >= startDate.getTime() &&
    session.timestamp <= endDate.getTime()
  );
};

export const getSessionStats = async (sessions: SessionData[]) => {
  const completedSessions = sessions.filter(s => s.completed);

  const totalSessions = completedSessions.length;
  const averageDuration = totalSessions > 0
    ? completedSessions.reduce((sum, s) => sum + s.duration, 0) / totalSessions
    : 0;

  const averageImprovement = totalSessions > 0
    ? completedSessions.reduce((sum, s) => sum + (s.beforeIntensity - s.afterIntensity), 0) / totalSessions
    : 0;

  const vibeTypeStats = completedSessions.reduce((acc, session) => {
    acc[session.vibeType] = (acc[session.vibeType] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  return {
    totalSessions,
    averageDuration,
    averageImprovement,
    vibeTypeStats,
  };
};

