<script lang="ts">
  import { onMount } from 'svelte';
  import { currentRoute } from '../stores';
  import { getRecentSessions, getSessionStats } from '../db/storage';
  import Button from '../ui/Button.svelte';
  import type { SessionData } from '../types';

  let sessions: SessionData[] = [];
  let stats = {
    totalSessions: 0,
    averageDuration: 0,
    averageImprovement: 0,
    vibeTypeStats: {} as Record<string, number>,
  };
  let chartCanvas: HTMLCanvasElement;
  let loading = true;
  let error = '';

  onMount(async () => {
    try {
      sessions = await getRecentSessions(7);
      stats = await getSessionStats(sessions);

      if (chartCanvas) {
        drawTrendsChart();
      }
    } catch (err) {
      error = 'Failed to load trends data';
      console.error('Trends loading error:', err);
    } finally {
      loading = false;
    }
  });

  const drawTrendsChart = () => {
    if (!chartCanvas) return;

    const ctx = chartCanvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const rect = chartCanvas.getBoundingClientRect();

    // Set actual size in memory (scaled to account for extra pixel density)
    chartCanvas.width = rect.width * dpr;
    chartCanvas.height = rect.height * dpr;

    // Scale the drawing context so everything draws at the correct size
    ctx.scale(dpr, dpr);

    // Set display size (css pixels)
    chartCanvas.style.width = rect.width + 'px';
    chartCanvas.style.height = rect.height + 'px';

    // Clear canvas
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, rect.width, rect.height);

    // Prepare data for last 7 days
    const today = new Date();
    const days = [];
    const sessionCounts = [];
    const improvementAvgs = [];

    for (let i = 6; i >= 0; i--) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      date.setHours(0, 0, 0, 0);

      const dayEnd = new Date(date);
      dayEnd.setHours(23, 59, 59, 999);

      const daySessions = sessions.filter(s =>
        s.timestamp >= date.getTime() && s.timestamp <= dayEnd.getTime() && s.completed
      );

      days.push(date.toLocaleDateString('en-US', { weekday: 'short' }));
      sessionCounts.push(daySessions.length);

      const avgImprovement = daySessions.length > 0
        ? daySessions.reduce((sum, s) => sum + (s.beforeIntensity - s.afterIntensity), 0) / daySessions.length
        : 0;
      improvementAvgs.push(avgImprovement);
    }

    // Chart dimensions
    const padding = 40;
    const chartWidth = rect.width - (padding * 2);
    const chartHeight = rect.height - (padding * 2);
    const barWidth = chartWidth / days.length * 0.6;
    const barSpacing = chartWidth / days.length;

    // Find max values for scaling
    const maxSessions = Math.max(...sessionCounts, 1);
    const maxImprovement = Math.max(...improvementAvgs.map(Math.abs), 1);

    // Draw session count bars
    ctx.fillStyle = '#6366f1';
    sessionCounts.forEach((count, i) => {
      const barHeight = (count / maxSessions) * (chartHeight / 2);
      const x = padding + (i * barSpacing) + (barSpacing - barWidth) / 2;
      const y = padding + (chartHeight / 2) - barHeight;

      ctx.fillRect(x, y, barWidth, barHeight);
    });

    // Draw improvement bars
    ctx.fillStyle = '#10b981';
    improvementAvgs.forEach((improvement, i) => {
      const barHeight = Math.abs(improvement / maxImprovement) * (chartHeight / 2);
      const x = padding + (i * barSpacing) + (barSpacing - barWidth) / 2;
      let y;

      if (improvement >= 0) {
        // Positive improvement (reduction in urge)
        y = padding + (chartHeight / 2);
        ctx.fillStyle = '#10b981'; // Green for positive
      } else {
        // Negative improvement (increase in urge)
        y = padding + (chartHeight / 2) - barHeight;
        ctx.fillStyle = '#ef4444'; // Red for negative
      }

      ctx.fillRect(x, y, barWidth, barHeight);
    });

    // Draw center line
    ctx.strokeStyle = '#888888';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding + chartHeight / 2);
    ctx.lineTo(padding + chartWidth, padding + chartHeight / 2);
    ctx.stroke();

    // Draw day labels
    ctx.fillStyle = '#888888';
    ctx.font = '12px -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", sans-serif';
    ctx.textAlign = 'center';
    days.forEach((day, i) => {
      const x = padding + (i * barSpacing) + barSpacing / 2;
      const y = rect.height - 10;
      ctx.fillText(day, x, y);
    });

    // Draw legend
    ctx.textAlign = 'left';
    ctx.fillStyle = '#6366f1';
    ctx.fillRect(padding, 10, 12, 12);
    ctx.fillStyle = '#ffffff';
    ctx.fillText('Sessions', padding + 20, 21);

    ctx.fillStyle = '#10b981';
    ctx.fillRect(padding + 100, 10, 12, 12);
    ctx.fillText('Improvement', padding + 120, 21);
  };

  const goHome = () => {
    currentRoute.set('home');
  };

  const formatDuration = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}m ${secs}s`;
  };

  // Reactive chart redraw
  $: if (chartCanvas && !loading) {
    setTimeout(drawTrendsChart, 100);
  }
</script>

<div class="trends">
  <div class="container">
    <header class="trends-header">
      <button class="back-button" on:click={goHome} aria-label="Go back">
        <svg viewBox="0 0 24 24" fill="currentColor">
          <path d="M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.42-1.41L7.83 13H20v-2z"/>
        </svg>
      </button>
      <h1 class="trends-title">Trends</h1>
      <div class="spacer"></div>
    </header>

    <main class="trends-main">
      {#if loading}
        <div class="loading">
          <div class="loading-spinner"></div>
          <p>Loading trends...</p>
        </div>
      {:else if error}
        <div class="error">
          <p>{error}</p>
          <Button variant="secondary" on:click={() => window.location.reload()}>
            Retry
          </Button>
        </div>
      {:else}
        <div class="trends-content">
          <!-- Stats overview -->
          <div class="stats-grid">
            <div class="stat-card">
              <span class="stat-value">{stats.totalSessions}</span>
              <span class="stat-label">Sessions</span>
            </div>
            <div class="stat-card">
              <span class="stat-value">{formatDuration(Math.round(stats.averageDuration))}</span>
              <span class="stat-label">Avg Duration</span>
            </div>
            <div class="stat-card">
              <span class="stat-value">
                {stats.averageImprovement >= 0 ? '+' : ''}{stats.averageImprovement.toFixed(1)}
              </span>
              <span class="stat-label">Avg Change</span>
            </div>
          </div>

          <!-- Chart -->
          <div class="chart-section">
            <h2>Last 7 Days</h2>
            <div class="chart-container">
              <canvas
                bind:this={chartCanvas}
                class="trends-chart"
                width="350"
                height="200"
              ></canvas>
            </div>
            <div class="chart-legend">
              <div class="legend-item">
                <div class="legend-color sessions"></div>
                <span>Daily Sessions</span>
              </div>
              <div class="legend-item">
                <div class="legend-color improvement"></div>
                <span>Urge Reduction</span>
              </div>
            </div>
          </div>

          <!-- Vibe type breakdown -->
          {#if Object.keys(stats.vibeTypeStats).length > 0}
            <div class="vibe-stats">
              <h3>Vibe Preferences</h3>
              <div class="vibe-breakdown">
                {#each Object.entries(stats.vibeTypeStats) as [vibeType, count]}
                  <div class="vibe-stat">
                    <span class="vibe-name">{vibeType.charAt(0).toUpperCase() + vibeType.slice(1)}</span>
                    <span class="vibe-count">{count}</span>
                  </div>
                {/each}
              </div>
            </div>
          {/if}

          {#if stats.totalSessions === 0}
            <div class="empty-state">
              <h3>No sessions yet</h3>
              <p>Complete some sessions to see your trends here.</p>
              <Button on:click={goHome}>Start First Session</Button>
            </div>
          {/if}
        </div>
      {/if}
    </main>
  </div>
</div>

