<script lang="ts">
  import { onMount } from 'svelte';
  import { currentRoute, userSettings } from '../stores';
  import { getStorage } from '../db/storage';
  import { getAudioEngine } from '../audio/engine';
  import Button from '../ui/Button.svelte';
  import Toggle from '../ui/Toggle.svelte';
  import type { UserSettings } from '../types';

  let settings: UserSettings = $userSettings;
  let saving = false;
  let showClearConfirm = false;

  const sessionLengthOptions = [
    { value: 60, label: '1 minute' },
    { value: 90, label: '1.5 minutes' },
    { value: 120, label: '2 minutes' },
  ];

  const saveSettings = async () => {
    saving = true;
    try {
      const storage = getStorage();
      await storage.updateSettings(settings);
      userSettings.set(settings);

      // Update audio engine
      const audioEngine = getAudioEngine();
      audioEngine.setEnabled(settings.audioEnabled);

      // Apply reduce motion preference
      if (settings.reduceMotion) {
        document.documentElement.style.setProperty('--animation-duration', '0.01ms');
        document.documentElement.style.setProperty('--transition-duration', '0.01ms');
      } else {
        document.documentElement.style.removeProperty('--animation-duration');
        document.documentElement.style.removeProperty('--transition-duration');
      }
    } catch (error) {
      console.error('Failed to save settings:', error);
    } finally {
      saving = false;
    }
  };

  const clearAllData = async () => {
    if (!showClearConfirm) {
      showClearConfirm = true;
      return;
    }

    try {
      const storage = getStorage();
      await storage.clearAllData();

      // Reset settings to defaults
      settings = {
        hapticsEnabled: true,
        audioEnabled: true,
        reduceMotion: false,
        sessionLength: 90,
        hasSeenDisclaimer: false,
      };

      await saveSettings();
      showClearConfirm = false;

      // Redirect to home
      currentRoute.set('home');
    } catch (error) {
      console.error('Failed to clear data:', error);
    }
  };

  const goHome = () => {
    currentRoute.set('home');
  };

  // Auto-save when settings change
  $: if (settings && JSON.stringify(settings) !== JSON.stringify($userSettings)) {
    saveSettings();
  }

  onMount(() => {
    settings = { ...$userSettings };
  });
</script>

<div class="settings">
  <div class="container">
    <header class="settings-header">
      <button class="back-button" on:click={goHome} aria-label="Go back">
        <svg viewBox="0 0 24 24" fill="currentColor">
          <path d="M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.42-1.41L7.83 13H20v-2z"/>
        </svg>
      </button>
      <h1 class="settings-title">Settings</h1>
      <div class="spacer"></div>
    </header>

    <main class="settings-main">
      <div class="settings-content">

        <!-- Experience Settings -->
        <section class="settings-section">
          <h2>Experience</h2>

          <div class="setting-item">
            <Toggle
              bind:checked={settings.hapticsEnabled}
              label="Haptic Feedback"
              description="Vibration during interactions"
            />
          </div>

          <div class="setting-item">
            <Toggle
              bind:checked={settings.audioEnabled}
              label="Audio Effects"
              description="Sound textures and feedback"
            />
          </div>

          <div class="setting-item">
            <Toggle
              bind:checked={settings.reduceMotion}
              label="Reduce Motion"
              description="Minimize animations and transitions"
            />
          </div>
        </section>

        <!-- Session Settings -->
        <section class="settings-section">
          <h2>Sessions</h2>

          <div class="setting-item">
            <div class="session-length-setting">
              <label class="setting-label">Default Session Length</label>
              <div class="session-length-options">
                {#each sessionLengthOptions as option}
                  <button
                    class="session-length-option"
                    class:active={settings.sessionLength === option.value}
                    on:click={() => settings.sessionLength = option.value}
                  >
                    {option.label}
                  </button>
                {/each}
              </div>
            </div>
          </div>
        </section>

        <!-- Data Settings -->
        <section class="settings-section">
          <h2>Data</h2>

          <div class="setting-item">
            <div class="data-info">
              <p class="text-muted">
                All your data is stored locally on this device. No information is sent to external servers.
              </p>
            </div>
          </div>

          <div class="setting-item">
            <div class="clear-data-section">
              <h3>Clear All Data</h3>
              <p class="text-muted mb-md">
                This will permanently delete all sessions, settings, and reset the app to its initial state.
              </p>

              {#if !showClearConfirm}
                <Button variant="secondary" on:click={clearAllData}>
                  Clear All Data
                </Button>
              {:else}
                <div class="confirm-clear">
                  <p class="confirm-text">Are you sure? This cannot be undone.</p>
                  <div class="confirm-buttons">
                    <Button variant="secondary" on:click={() => showClearConfirm = false}>
                      Cancel
                    </Button>
                    <Button variant="primary" on:click={clearAllData}>
                      Yes, Clear All
                    </Button>
                  </div>
                </div>
              {/if}
            </div>
          </div>
        </section>

        <!-- About Section -->
        <section class="settings-section">
          <h2>About</h2>

          <div class="setting-item">
            <div class="about-info">
              <h3>Vibe v0.0.1</h3>
              <p class="text-muted">
                A sensory-substitution app for redirecting tactile urges through multimodal feedback.
              </p>
              <p class="disclaimer-reminder text-muted mt-md">
                <strong>Remember:</strong> Vibe is a support tool, not medical advice.
                If you're experiencing persistent urges or self-harm thoughts, please consult
                with a healthcare professional.
              </p>
            </div>
          </div>
        </section>

      </div>
    </main>

    {#if saving}
      <div class="saving-indicator">
        <div class="saving-spinner"></div>
        <span>Saving...</span>
      </div>
    {/if}
  </div>
</div>

