import type { VibeImplementation, VibeInstance, VibeOptions } from '../types';
import { hapticsAdapter } from '../haptics/adapter';
import { getAudioEngine } from '../audio/engine';

/**
 * Press vibe implementation - long-press creates pulsing pressure ripples:
 * - Visual: expanding rings with spring easing
 * - Haptics: ramp-up vibration while held, release "thunk"
 * - Audio: low-frequency thump synced to ripple
 */

interface Ripple {
  x: number;
  y: number;
  startTime: number;
  maxRadius: number;
  intensity: number;
  isActive: boolean;
  releaseTime?: number;
}

interface PressState {
  isPressed: boolean;
  startTime: number;
  x: number;
  y: number;
  intensity: number;
}

class PressVibeInstance implements VibeInstance {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private options: VibeOptions;
  private animationId: number | null = null;
  private ripples: Ripple[] = [];
  private pressState: PressState | null = null;
  private pressTimer: number | null = null;
  private hapticInterval: number | null = null;
  private audioEngine = getAudioEngine();

  // Performance tracking
  private frameCount = 0;
  private lastFpsCheck = performance.now();

  // Constants
  private readonly PRESS_THRESHOLD = 150; // ms for long-press detection
  private readonly RIPPLE_DURATION = 2000; // ms for ripple animation
  private readonly HAPTIC_INTERVAL = 250; // ms between haptic pulses during press

  constructor(canvas: HTMLCanvasElement, options: VibeOptions) {
    this.canvas = canvas;
    this.options = options;

    const ctx = canvas.getContext('2d');
    if (!ctx) {
      throw new Error('Could not get 2D context from canvas');
    }
    this.ctx = ctx;

    this.setupCanvas();
    this.bindEvents();
    this.startRenderLoop();
  }

  private setupCanvas(): void {
    const dpr = window.devicePixelRatio || 1;
    const rect = this.canvas.getBoundingClientRect();

    // Set actual size in memory (scaled for pixel density)
    this.canvas.width = rect.width * dpr;
    this.canvas.height = rect.height * dpr;

    // Scale drawing context
    this.ctx.scale(dpr, dpr);

    // Set display size
    this.canvas.style.width = rect.width + 'px';
    this.canvas.style.height = rect.height + 'px';

    // Configure context for smooth rendering
    this.ctx.imageSmoothingEnabled = true;
  }

  private bindEvents(): void {
    // Mouse events
    this.canvas.addEventListener('mousedown', this.handlePointerStart.bind(this));
    this.canvas.addEventListener('mouseup', this.handlePointerEnd.bind(this));
    this.canvas.addEventListener('mouseleave', this.handlePointerEnd.bind(this));

    // Touch events
    this.canvas.addEventListener('touchstart', this.handleTouchStart.bind(this), { passive: false });
    this.canvas.addEventListener('touchend', this.handlePointerEnd.bind(this));
    this.canvas.addEventListener('touchcancel', this.handlePointerEnd.bind(this));

    // Keyboard alternative (accessibility)
    this.canvas.addEventListener('keydown', this.handleKeyDown.bind(this));
    this.canvas.addEventListener('keyup', this.handleKeyUp.bind(this));

    // Make canvas focusable
    this.canvas.tabIndex = 0;
  }

  private handlePointerStart(event: MouseEvent): void {
    event.preventDefault();
    const rect = this.canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    this.startPress(x, y);
  }

  private handlePointerEnd(event: Event): void {
    event.preventDefault();
    this.endPress();
  }

  private handleTouchStart(event: TouchEvent): void {
    event.preventDefault();
    const touch = event.touches[0];
    if (!touch) return;

    const rect = this.canvas.getBoundingClientRect();
    const x = touch.clientX - rect.left;
    const y = touch.clientY - rect.top;

    this.startPress(x, y);
  }

  private handleKeyDown(event: KeyboardEvent): void {
    if (event.key === ' ' || event.key === 'Enter') {
      event.preventDefault();
      if (!this.pressState) {
        // Start press at center of canvas
        const rect = this.canvas.getBoundingClientRect();
        const x = rect.width / 2;
        const y = rect.height / 2;
        this.startPress(x, y);
      }
    }
  }

  private handleKeyUp(event: KeyboardEvent): void {
    if (event.key === ' ' || event.key === 'Enter') {
      event.preventDefault();
      this.endPress();
    }
  }

  private startPress(x: number, y: number): void {
    if (this.pressState) return; // Already pressing

    const now = performance.now();
    this.pressState = {
      isPressed: true,
      startTime: now,
      x,
      y,
      intensity: 0
    };

    // Set timer for long-press detection
    this.pressTimer = window.setTimeout(() => {
      this.onLongPress();
    }, this.PRESS_THRESHOLD);

    // Initial light haptic feedback
    if (this.options.hapticsEnabled) {
      hapticsAdapter.vibrate(5);
    }
  }

  private onLongPress(): void {
    if (!this.pressState) return;

    // Create initial ripple
    const rect = this.canvas.getBoundingClientRect();
    const maxRadius = Math.max(rect.width, rect.height) * 0.8;

    this.ripples.push({
      x: this.pressState.x,
      y: this.pressState.y,
      startTime: performance.now(),
      maxRadius,
      intensity: 1,
      isActive: true
    });

    // Play press audio
    if (this.options.audioEnabled) {
      // Fire and forget - don't block on audio
      this.audioEngine.playPress(0.8).catch(err =>
        console.debug('Audio playback failed:', err)
      );
    }

    // Start haptic pulse pattern
    if (this.options.hapticsEnabled) {
      this.startHapticPulse();
    }

    this.pressTimer = null;
  }

  private startHapticPulse(): void {
    if (this.hapticInterval) return;

    this.hapticInterval = window.setInterval(() => {
      if (!this.pressState?.isPressed) {
        this.stopHapticPulse();
        return;
      }

      // Increasing intensity over time
      const duration = performance.now() - this.pressState.startTime;
      const intensity = Math.min(duration / 1000, 1); // 0-1 over 1 second
      const vibrationDuration = Math.floor(10 + (intensity * 15)); // 10-25ms

      hapticsAdapter.vibrate(vibrationDuration);
    }, this.HAPTIC_INTERVAL);
  }

  private stopHapticPulse(): void {
    if (this.hapticInterval) {
      clearInterval(this.hapticInterval);
      this.hapticInterval = null;
    }
  }

  private endPress(): void {
    if (!this.pressState) return;

    const now = performance.now();
    const pressDuration = now - this.pressState.startTime;

    // Clear press timer if still pending
    if (this.pressTimer) {
      clearTimeout(this.pressTimer);
      this.pressTimer = null;
    }

    // Stop haptic pulse
    this.stopHapticPulse();

    // If it was a long press, create release ripple and effects
    if (pressDuration >= this.PRESS_THRESHOLD) {
      // Mark active ripples for release
      this.ripples.forEach(ripple => {
        if (ripple.isActive) {
          ripple.isActive = false;
          ripple.releaseTime = now;
        }
      });

      // Create release ripple
      const rect = this.canvas.getBoundingClientRect();
      const maxRadius = Math.max(rect.width, rect.height) * 0.6;

      this.ripples.push({
        x: this.pressState.x,
        y: this.pressState.y,
        startTime: now,
        maxRadius,
        intensity: 0.6,
        isActive: false,
        releaseTime: now
      });

      // Release haptic "thunk"
      if (this.options.hapticsEnabled) {
        hapticsAdapter.vibrate([20, 10, 15]);
      }

      // Release audio thump
      if (this.options.audioEnabled) {
        // Fire and forget - don't block on audio
        this.audioEngine.playPress(1.0).catch(err =>
          console.debug('Audio playback failed:', err)
        );
      }
    } else {
      // Short press - just light feedback
      if (this.options.hapticsEnabled) {
        hapticsAdapter.vibrate(8);
      }
    }

    this.pressState = null;
  }

  private startRenderLoop(): void {
    const render = () => {
      this.render();
      this.frameCount++;

      // Performance monitoring (keep under 2% main thread)
      if (this.frameCount % 60 === 0) {
        const now = performance.now();
        const fps = 60000 / (now - this.lastFpsCheck);
        this.lastFpsCheck = now;

        if (fps < 55) {
          console.warn('Press vibe performance degraded:', fps, 'fps');
        }
      }

      this.animationId = requestAnimationFrame(render);
    };

    this.animationId = requestAnimationFrame(render);
  }

  private render(): void {
    const now = performance.now();

    // Clear canvas with dark background
    this.ctx.fillStyle = '#1a1a1a';
    this.ctx.fillRect(0, 0, this.canvas.width / (window.devicePixelRatio || 1),
                            this.canvas.height / (window.devicePixelRatio || 1));

    // Update and draw ripples
    this.ripples = this.ripples.filter(ripple => {
      const age = now - ripple.startTime;
      if (age > this.RIPPLE_DURATION) return false;

      this.drawRipple(ripple, now);
      return true;
    });

    // Draw current press indicator
    if (this.pressState) {
      this.drawPressIndicator(now);
    }
  }

  private drawRipple(ripple: Ripple, now: number): void {
    const age = now - ripple.startTime;
    let progress = age / this.RIPPLE_DURATION;

    // Different animation for active vs released ripples
    if (ripple.isActive) {
      // Pulsing expansion while pressed
      const pulseSpeed = 2; // Hz
      const pulse = Math.sin(age * pulseSpeed * Math.PI / 500) * 0.3 + 0.7;
      progress = Math.min(progress * 2, 1) * pulse;
    } else {
      // Spring easing for release
      progress = this.easeOutElastic(Math.min(progress, 1));
    }

    const radius = ripple.maxRadius * progress;
    const alpha = ripple.intensity * (1 - (age / this.RIPPLE_DURATION));

    if (alpha <= 0) return;

    this.ctx.save();

    // Main ripple ring
    this.ctx.beginPath();
    this.ctx.arc(ripple.x, ripple.y, radius, 0, Math.PI * 2);
    this.ctx.strokeStyle = `rgba(99, 102, 241, ${alpha * 0.8})`;
    this.ctx.lineWidth = 3;
    this.ctx.stroke();

    // Inner glow if not reducing motion
    if (!this.options.reduceMotion) {
      this.ctx.shadowColor = `rgba(99, 102, 241, ${alpha * 0.5})`;
      this.ctx.shadowBlur = 15;
      this.ctx.stroke();
    }

    // Fill with gradient
    const gradient = this.ctx.createRadialGradient(
      ripple.x, ripple.y, 0,
      ripple.x, ripple.y, radius
    );
    gradient.addColorStop(0, `rgba(99, 102, 241, ${alpha * 0.1})`);
    gradient.addColorStop(0.7, `rgba(99, 102, 241, ${alpha * 0.05})`);
    gradient.addColorStop(1, 'rgba(99, 102, 241, 0)');

    this.ctx.fillStyle = gradient;
    this.ctx.fill();

    this.ctx.restore();
  }

  private drawPressIndicator(now: number): void {
    if (!this.pressState) return;

    const duration = now - this.pressState.startTime;
    const progress = Math.min(duration / this.PRESS_THRESHOLD, 1);

    // Show building pressure before long-press threshold
    if (duration < this.PRESS_THRESHOLD) {
      const radius = 20 + (progress * 10);
      const alpha = 0.3 + (progress * 0.4);

      this.ctx.save();
      this.ctx.beginPath();
      this.ctx.arc(this.pressState.x, this.pressState.y, radius, 0, Math.PI * 2);
      this.ctx.fillStyle = `rgba(99, 102, 241, ${alpha})`;
      this.ctx.fill();

      // Progress ring
      this.ctx.beginPath();
      this.ctx.arc(this.pressState.x, this.pressState.y, radius + 5,
                   -Math.PI / 2, -Math.PI / 2 + (progress * Math.PI * 2));
      this.ctx.strokeStyle = `rgba(255, 255, 255, ${alpha})`;
      this.ctx.lineWidth = 2;
      this.ctx.stroke();

      this.ctx.restore();
    }
  }

  // Elastic easing function for spring effect
  private easeOutElastic(x: number): number {
    const c4 = (2 * Math.PI) / 3;
    return x === 0 ? 0 : x === 1 ? 1 :
           Math.pow(2, -10 * x) * Math.sin((x * 10 - 0.75) * c4) + 1;
  }

  unmount(): void {
    if (this.animationId) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }

    // Clear timers
    if (this.pressTimer) {
      clearTimeout(this.pressTimer);
      this.pressTimer = null;
    }

    this.stopHapticPulse();

    // Remove event listeners
    this.canvas.removeEventListener('mousedown', this.handlePointerStart.bind(this));
    this.canvas.removeEventListener('mouseup', this.handlePointerEnd.bind(this));
    this.canvas.removeEventListener('mouseleave', this.handlePointerEnd.bind(this));
    this.canvas.removeEventListener('touchstart', this.handleTouchStart.bind(this));
    this.canvas.removeEventListener('touchend', this.handlePointerEnd.bind(this));
    this.canvas.removeEventListener('touchcancel', this.handlePointerEnd.bind(this));
    this.canvas.removeEventListener('keydown', this.handleKeyDown.bind(this));
    this.canvas.removeEventListener('keyup', this.handleKeyUp.bind(this));

    // Clear canvas
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

    // Reset state
    this.pressState = null;
    this.ripples = [];
  }
}

export const pressVibe: VibeImplementation = {
  mount(canvas: HTMLCanvasElement, options: VibeOptions): VibeInstance {
    return new PressVibeInstance(canvas, options);
  }
};

