<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import { currentRoute, userSettings } from '../stores';
  import { sessionMachine, getSessionDuration } from '../state/sessionMachine.ts';
  import { createActor } from 'xstate';
  import { readable } from 'svelte/store';
  import { getStorage } from '../db/storage';
  import Button from '../ui/Button.svelte';
  import Slider from '../ui/Slider.svelte';
  import ProgressRing from '../ui/ProgressRing.svelte';
  import type { VibeType } from '../types';

  // Vibe implementations
  import { scratchVibe } from '../vibes/scratch';
  import { pressVibe } from '../vibes/press';

  // Create XState v5 actor and reactive store
  const actor = createActor(sessionMachine);
  actor.start();

  const state = readable(actor.getSnapshot(), (set) => {
    const subscription = actor.subscribe(set);
    return () => subscription.unsubscribe();
  });

  const send = actor.send.bind(actor);

  let canvasElement: HTMLCanvasElement;
  let vibeInstance: { unmount: () => void } | null = null;
  let beforeIntensity = 5;
  let afterIntensity = 5;
  let sessionProgress = 0;
  let timeRemaining = 0;
  let progressInterval: number | null = null;

  // Get vibe type from URL or default
  let vibeType: VibeType = 'scratch'; // This would come from navigation state

  const vibeImplementations = {
    scratch: scratchVibe,
    press: pressVibe,
  };

  const startSession = () => {
    send({
      type: 'START_SESSION',
      vibeType,
      beforeIntensity,
      sessionLength: $userSettings.sessionLength,
    });
  };

  const beginVibe = () => {
    send({ type: 'BEGIN_VIBE' });

    // Mount the vibe implementation
    const implementation = vibeImplementations[vibeType];
    if (canvasElement && implementation) {
      vibeInstance = implementation.mount(canvasElement, {
        hapticsEnabled: $userSettings.hapticsEnabled,
        audioEnabled: $userSettings.audioEnabled,
        reduceMotion: $userSettings.reduceMotion,
        onComplete: () => {
          send({ type: 'COMPLETE_VIBE' });
        },
      });

      // Start progress tracking
      startProgressTracking();
    }
  };

  const startProgressTracking = () => {
    if (progressInterval) clearInterval(progressInterval);

    progressInterval = setInterval(() => {
      const duration = getSessionDuration($state.context);
      const totalTime = $state.context.sessionLength;
      sessionProgress = Math.min((duration / totalTime) * 100, 100);
      timeRemaining = Math.max(totalTime - duration, 0);

      // Auto-complete if time is up
      if (timeRemaining === 0 && $state.matches('running')) {
        send({ type: 'COMPLETE_VIBE' });
      }
    }, 100);
  };

  const submitReview = async () => {
    send({ type: 'SUBMIT_REVIEW', afterIntensity });

    // Save session to storage
    try {
      const storage = getStorage();
      await storage.addSession({
        timestamp: $state.context.startTime,
        vibeType: $state.context.vibeType,
        beforeIntensity: $state.context.beforeIntensity,
        afterIntensity,
        duration: getSessionDuration($state.context),
        completed: true,
      });
    } catch (error) {
      console.error('Failed to save session:', error);
    }
  };

  const goHome = () => {
    send({ type: 'RESET' });
    currentRoute.set('home');
  };

  const emergency = () => {
    send({ type: 'RESET' });
    currentRoute.set('home');
  };

  // Cleanup on component destroy
  onDestroy(() => {
    if (vibeInstance) {
      vibeInstance.unmount();
      vibeInstance = null;
    }
    if (progressInterval) {
      clearInterval(progressInterval);
      progressInterval = null;
    }
  });

  // Format time display
  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  $: currentState = $state.value;
  $: sessionContext = $state.context;
</script>

<div class="session">
  <div class="container">
    <!-- Header with progress -->
    <header class="session-header">
      <button class="back-button" on:click={goHome} aria-label="Go back">
        <svg viewBox="0 0 24 24" fill="currentColor">
          <path d="M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.42-1.41L7.83 13H20v-2z"/>
        </svg>
      </button>

      <div class="session-info">
        <h1 class="session-title">
          {vibeType === 'scratch' ? 'Scratch' : 'Press'} Session
        </h1>
        {#if currentState === 'running'}
          <p class="session-time">{formatTime(timeRemaining)}</p>
        {/if}
      </div>

      <button class="emergency-button" on:click={emergency} aria-label="Emergency stop">
        <svg viewBox="0 0 24 24" fill="currentColor">
          <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/>
        </svg>
      </button>
    </header>

    <!-- Main content based on session state -->
    <main class="session-main">
      {#if currentState === 'precheck'}
        <div class="precheck">
          <h2>Settle in. You can stop anytime.</h2>
          <p class="text-muted mb-lg">
            Rate your urge intensity right now, then we'll begin.
          </p>

          <div class="intensity-slider">
            <Slider
              bind:value={beforeIntensity}
              min={0}
              max={10}
              label="Urge intensity now"
              showValue={true}
            />
          </div>

          <div class="session-length">
            <p class="text-muted">Session length: {$userSettings.sessionLength}s</p>
          </div>

          <Button size="lg" fullWidth on:click={beginVibe}>
            Start Session
          </Button>
        </div>

      {:else if currentState === 'running'}
        <div class="running">
          <div class="progress-container">
            <ProgressRing
              progress={sessionProgress}
              size={120}
              text={formatTime(timeRemaining)}
            />
          </div>

          <div class="canvas-container">
            <canvas
              bind:this={canvasElement}
              class="vibe-canvas"
              width="800"
              height="600"
            ></canvas>
            <div class="canvas-instructions">
              {#if vibeType === 'scratch'}
                <p>Draw across the surface with your finger</p>
              {:else}
                <p>Press and hold to create ripples</p>
              {/if}
            </div>
          </div>

          <Button variant="secondary" on:click={() => send({ type: 'COMPLETE_VIBE' })}>
            End Early
          </Button>
        </div>

      {:else if currentState === 'cooldown'}
        <div class="cooldown">
          <h2>Nice work</h2>
          <p class="text-muted">Taking a moment to settle...</p>
          <div class="cooldown-animation">
            <div class="pulse"></div>
          </div>
        </div>

      {:else if currentState === 'review'}
        <div class="review">
          <h2>How strong is the urge now?</h2>
          <p class="text-muted mb-lg">
            Compare to how you felt before the session.
          </p>

          <div class="intensity-comparison">
            <div class="intensity-before">
              <span class="intensity-label">Before</span>
              <span class="intensity-value">{sessionContext.beforeIntensity}</span>
            </div>
            <div class="intensity-arrow">→</div>
            <div class="intensity-after">
              <span class="intensity-label">After</span>
              <span class="intensity-value">{afterIntensity}</span>
            </div>
          </div>

          <div class="intensity-slider">
            <Slider
              bind:value={afterIntensity}
              min={0}
              max={10}
              label="Urge intensity now"
              showValue={true}
            />
          </div>

          <Button size="lg" fullWidth on:click={submitReview}>
            Complete Session
          </Button>
        </div>

      {:else if currentState === 'completed'}
        <div class="completed">
          <h2>Session Complete</h2>
          <div class="completion-stats">
            <div class="stat">
              <span class="stat-label">Duration</span>
              <span class="stat-value">{formatTime(getSessionDuration(sessionContext))}</span>
            </div>
            <div class="stat">
              <span class="stat-label">Change</span>
              <span class="stat-value">
                {sessionContext.beforeIntensity - afterIntensity > 0 ? '-' : '+'}
                {Math.abs(sessionContext.beforeIntensity - afterIntensity)}
              </span>
            </div>
          </div>
          <p class="text-muted">Returning to home...</p>
        </div>

      {:else}
        <!-- Idle state - shouldn't normally be seen -->
        <div class="idle">
          <Button on:click={startSession}>Start Session</Button>
        </div>
      {/if}
    </main>
  </div>
</div>

