import type { HapticsAdapter } from '../types';

/**
 * Web vibration API adapter for haptic feedback.
 * Uses navigator.vibrate() with graceful fallbacks.
 */
export const webVibrationAdapter: HapticsAdapter = {
  async vibrate(pattern: number | number[]): Promise<void> {
    try {
      if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
        navigator.vibrate(pattern);
      }
    } catch (error) {
      // Silently fail - some browsers don't support vibration
      console.debug('Vibration not supported:', error);
    }
  },

  canVibrate(): boolean {
    return typeof navigator !== 'undefined' && 'vibrate' in navigator;
  }
};

