<script lang="ts">
  export let progress: number = 0; // 0-100
  export let size: number = 120;
  export let strokeWidth: number = 8;
  export let color: string = 'var(--color-accent)';
  export let backgroundColor: string = 'var(--color-surface)';
  export let showText: boolean = true;
  export let text: string = '';
  export let animated: boolean = true;

  $: radius = (size - strokeWidth) / 2;
  $: circumference = 2 * Math.PI * radius;
  $: strokeDashoffset = circumference - (progress / 100) * circumference;
  $: center = size / 2;

  // Format progress text
  $: displayText = text || `${Math.round(progress)}%`;
</script>

<div class="progress-ring" style="width: {size}px; height: {size}px;">
  <svg width={size} height={size} class="progress-svg">
    <!-- Background circle -->
    <circle
      cx={center}
      cy={center}
      r={radius}
      stroke={backgroundColor}
      stroke-width={strokeWidth}
      fill="transparent"
      class="progress-bg"
    />

    <!-- Progress circle -->
    <circle
      cx={center}
      cy={center}
      r={radius}
      stroke={color}
      stroke-width={strokeWidth}
      fill="transparent"
      stroke-dasharray={circumference}
      stroke-dashoffset={strokeDashoffset}
      stroke-linecap="round"
      class="progress-bar"
      class:animated
      transform="rotate(-90 {center} {center})"
    />
  </svg>

  {#if showText}
    <div class="progress-text">
      <span class="progress-value">{displayText}</span>
    </div>
  {/if}
</div>

<style>
  .progress-ring {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .progress-svg {
    transform: rotate(0deg);
  }

  .progress-bg {
    opacity: 0.3;
  }

  .progress-bar {
    transition: stroke-dashoffset 0.3s ease;
  }

  .progress-bar.animated {
    transition: stroke-dashoffset 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .progress-text {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    pointer-events: none;
  }

  .progress-value {
    font-size: calc(var(--font-size-base) * 1.2);
    font-weight: 700;
    color: var(--color-text);
    line-height: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    .progress-bar {
      transition: none;
    }
  }
</style>

